// V50 : calculs de carrière fictifs ; aucun effet de bord.
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.CDRugbyWorld=api})(typeof globalThis==='object'?globalThis:null,function(){const num=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;
function rivalry(a,b,history){if(typeof a!=='string'||typeof b!=='string'||a===b||!Array.isArray(history))throw Error('Données invalides');const games=history.filter(x=>x&&((x.home===a&&x.away===b)||(x.home===b&&x.away===a))&&Number.isFinite(x.homeScore)&&Number.isFinite(x.awayScore));let wa=0,wb=0,draw=0;for(const g of games){const as=g.home===a?g.homeScore:g.awayScore,bs=g.home===b?g.homeScore:g.awayScore;if(as>bs)wa++;else if(bs>as)wb++;else draw++}return {matches:games.length,winsA:wa,winsB:wb,draws:draw,competitive:games.length>=3&&Math.abs(wa-wb)<=2};}function awards(players){if(!Array.isArray(players))throw Error('Données invalides');return players.filter(p=>p&&typeof p.id==='string'&&num(p.rating)&&num(p.minutes)&&num(p.tries)).map(p=>({id:p.id,score:p.rating*.6+Math.min(30,p.minutes/80)+p.tries*2})).sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id)).slice(0,5);}
return Object.freeze({rivalry,awards});});
